.empty{text-align:center;color:var(--mut);padding:28px 0}
/* the kind of each upstream item, so an issue never reads as a PR */
.kd{flex:none;font-weight:600;font-size:12px;line-height:1;border-radius:7px;padding:5px 8px;background:var(--test-bg);color:var(--test-d)}
.kd.k-issue{background:var(--gold-bg);color:var(--gold-d)}
.kd.k-discussion{background:var(--audit-bg);color:var(--audit-d)}
.kd.k-comment{background:var(--ok-bg);color:var(--ok-d)}
.pr-top .repo{flex:1}

/* real-world impact: the claim, the real org logos, then the carousel as proof */
.impact{margin-top:clamp(64px,8vw,96px);text-align:center}
.impact h2{max-width:19em}
.orgs{list-style:none;padding:0;margin:28px auto 0;display:flex;flex-wrap:wrap;justify-content:center;gap:10px 26px}
.orgs a{display:inline-flex;align-items:center;gap:9px;font-weight:600;font-size:15px;color:var(--ink);text-decoration:none;padding:4px 0}
.orgs a:hover{color:var(--cd)}
.orgs img{width:30px;height:30px;border-radius:8px;box-shadow:0 0 0 1px var(--line),var(--sh);background:var(--panel)}
@media(max-width:600px){.orgs{gap:8px 18px}.orgs a{font-size:14px}.orgs img{width:26px;height:26px}}

/* FirstRun in an H2: the app icon, then a yellow highlighter stroke behind the word */
.fr{white-space:nowrap;display:inline-flex;align-items:baseline;gap:.16em}
.fr-i{width:.78em;height:.78em;flex:none;align-self:center;transform:translateY(.02em);border-radius:.18em;box-shadow:0 2px 6px -2px oklch(40% .12 256/.35)}
.fr mark{color:inherit;padding:0 .1em;margin:0 -.02em;border-radius:.12em .3em .16em .28em;
 background:linear-gradient(100deg,oklch(92% .15 98/.0) 0,oklch(91% .16 98/.85) 4%,oklch(90% .17 96/.75) 60%,oklch(91% .16 98/.9) 96%,oklch(92% .15 98/0) 100%) 0 78%/100% .5em no-repeat;
 -webkit-box-decoration-break:clone;box-decoration-break:clone}

/* Doc-audit: three real findings, one row each, linked into the board */
.finds{list-style:none;padding:0;margin:clamp(40px,5vw,56px) auto 0;max-width:780px;background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--lift);overflow:hidden;text-align:left}
.finds li+li{border-top:1px solid var(--line)}
.fd{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:6px 16px;padding:16px 20px;color:var(--ink);text-decoration:none;transition:background .2s}
.fd:hover{background:var(--hover)}
.fd:hover b{color:var(--cd);text-decoration:underline;text-underline-offset:3px}
.fd:focus-visible{outline-offset:-3px;border-radius:0}
.fk{font-weight:600;font-size:12px;line-height:1;border-radius:7px;padding:6px 9px;white-space:nowrap}
.fk.k-st{background:var(--bad-bg);color:var(--bad)}
.fk.k-nd{background:var(--audit-bg);color:var(--audit-d)}
.fm{display:flex;flex-direction:column;gap:2px;min-width:0}
.fm b{font:600 15px/1.3 var(--mono);overflow-wrap:anywhere}
.fm small{font:500 12.5px/1.3 var(--mono);color:var(--mut)}
.fx{display:flex;flex-direction:column;align-items:flex-end;gap:2px;font-size:13.5px;color:var(--mut);text-align:right;white-space:nowrap}
.fx [data-f=since]{color:var(--ink);font-weight:600}
@media(max-width:600px){.fd{grid-template-columns:minmax(0,1fr);padding:14px 16px}.fk{justify-self:start}.fx{align-items:flex-start;text-align:left;flex-direction:row;flex-wrap:wrap;gap:2px 12px;white-space:normal}}

/* compare: the one-line honest edge under the H2 */
.edge{text-align:center;margin:16px auto 0;max-width:34em;font-size:clamp(16px,1.6vw,18px);color:var(--mut);text-wrap:balance}

